create table if not exists public.timeline_daw_normalization_recovery_receipts(id text primary key,owner_id uuid not null references auth.users(id) on delete cascade,session_id text not null,retention_receipt_id text not null references public.timeline_daw_normalization_retention_receipts(id) on delete cascade,before_failures jsonb not null,after_failures jsonb not null,recovered_paths jsonb not null,created_at timestamptz not null default now());alter table public.timeline_daw_normalization_recovery_receipts enable row level security;create policy timeline_daw_normalization_recovery_owner on public.timeline_daw_normalization_recovery_receipts for all to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());